function newEgg(){const options=['Pichu','Eevee','Togepi','Dratini','Bulbasaur','Squirtle','Tyrogue','Elekid','Happiny','Cleffa','Igglybuff','Smoochum','Magby','Chikorita','Cyndaquil','Totodile','Treecko','Torchic','Mudkip','Azurill','Wynaut'].filter(name=>lines.some(l=>l.names.includes(name)));if(!options.length)return;const name=options[Math.floor(Math.random()*options.length)];w.eggs.push({id:'egg-'+(++w.eggSerial),name,progress:0,need:12,active:w.eggs.filter(e=>e.active).length<2});}
